
import type { GiftCardProductConfiguration } from './GiftCardProductConfiguration.js';
import type { ImageRequest } from './ImageRequest.js';
import type { InventoryItemCreateRequest } from './InventoryItemCreateRequest.js';
import type { MoneyValue } from './MoneyValue.js';
import type { ProductVariantSelectedOptionRequest } from './ProductVariantSelectedOptionRequest.js';

export type ProductVariantRequest = { "barcode"?: string; "delivery_profile_id"?: string; /** Caller-owned identifier for this resource in an external system. minLength: 1. maxLength: 255. */ "external_reference_id"?: string; /** Only valid for product_type gift_card. Omission creates a fixed denomination at unit_price_money. Discounted pricing requires an explicit face_value_money and price_mode discounted. */ "gift_card_configuration"?: GiftCardProductConfiguration; /** The complete desired gallery in display order. The first image is primary. Send [] to clear the gallery. minItems: 0. maxItems: 8. */ "images"?: Array<ImageRequest>; "inventory_item"?: InventoryItemCreateRequest; "inventory_item_id"?: string; /** Flint line-item tax category. */ "line_item_tax_category"?: "general" | "physical_goods" | "digital_goods" | "software" | "saas" | "services" | "professional_services" | "food" | "prepared_food" | "clothing" | "medical_goods" | "admission" | (string & {}); "metadata"?: Record<string, string>; /** Attached modifier set. Send null on update to remove it. pattern: ^ms_[0-9A-HJKMNP-TV-Z]{26}$. */ "modifier_set_id"?: string | null; "name"?: string; /** Format: int32. */ "position"?: number; "selected_option_values"?: Array<ProductVariantSelectedOptionRequest>; "sku"?: string; "status"?: "active" | "inactive" | (string & {}); "taxable"?: boolean; "unit_price_money": MoneyValue; };
